create table public.cda_orc_papeis(id uuid primary key default gen_random_uuid(),nome text not null check(length(trim(nome))>0),ativo boolean not null default true,criado_em timestamptz not null default now());
create unique index cda_orc_papeis_nome on public.cda_orc_papeis(lower(trim(nome)));
create table public.cda_orc_pessoas(id uuid primary key default gen_random_uuid(),nome text not null check(length(trim(nome))>0),papeis uuid[] not null check(cardinality(papeis)>0),ativo boolean not null default true,tipo text check(tipo in ('fisica','juridica')),documento text,email text,telefone text,endereco text,observacoes text,criado_em timestamptz not null default now());
alter table public.cda_orc_papeis enable row level security;
alter table public.cda_orc_pessoas enable row level security;
grant select,insert,update on public.cda_orc_papeis,public.cda_orc_pessoas to authenticated;
revoke all on public.cda_orc_papeis,public.cda_orc_pessoas from anon;
create policy leitura on public.cda_orc_papeis for select to authenticated using (exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))));create policy inclusao on public.cda_orc_papeis for insert to authenticated with check (exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));create policy edicao on public.cda_orc_papeis for update to authenticated using (exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita')) with check (exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));
create policy leitura on public.cda_orc_pessoas for select to authenticated using (exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))));create policy inclusao on public.cda_orc_pessoas for insert to authenticated with check (exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));create policy edicao on public.cda_orc_pessoas for update to authenticated using (exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita')) with check (exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists (select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));
create function public.cda_orc_validar_papeis() returns trigger language plpgsql security invoker set search_path=public as $$ begin if exists(select 1 from unnest(new.papeis) as ref(papel_id) where not exists(select 1 from public.cda_orc_papeis p where p.id=ref.papel_id)) then raise exception 'Papel inexistente';end if;return new;end;$$;
create trigger validar_papeis before insert or update of papeis on public.cda_orc_pessoas for each row execute function public.cda_orc_validar_papeis();
insert into public.cda_orc_papeis(nome) values ('Owner Product'),('Parceiro Cultural'),('Cliente'),('Parceiro Fabricação'),('Fornecedor'),('Prestador de Serviços');
insert into public.cda_orc_pessoas(nome,papeis) select nome,array(select id from public.cda_orc_papeis where nome=any(papeis)) from (values ('Ciclo Arte',array['Owner Product']),('Sandy & Junior',array['Parceiro Cultural','Cliente']),('Dimona',array['Parceiro Fabricação']),('Fornecedores Diversos',array['Fornecedor']),('Prestadores de Serviços Diversos',array['Prestador de Serviços'])) s(nome,papeis);